		for i < b && !data.Less(i, i-1) {
			i++
		}
		if i == b {
			return true
		}
		if b-a < 50 {
			return false
		}
		data.Swap(i, i-1)
		if i-a >= 2 {
			for j := i - 1; j >= 1; j-- {
				if !data.Less(j, j-1) {
					break
				}
				data.Swap(j, j-1)
			}
		}
		if b-i >= 2 {
			for j := i + 1; j < b; j++ {
				if !data.Less(j, j-1) {
					break
				}
				data.Swap(j, j-1)
			}
		}
	}
	return false
}

// scatter exchanges three elements in the middle of data[a:b] with
// others, chosen by a sequence that depends on the length alone.
func scatter(data Interface, a, b int) {
	length := b - a
	if length < 8 {
		return
	}
	random := length
	mask := (1 << bitLength(length)) - 1
	middle := a + length/4*2
	for at := middle - 1; at <= middle+1; at++ {
		random = xorshift(random)
		other := random & mask
		if other >= length {
			other -= length
		}
		data.Swap(at, a+other)
	}
